const PILOT_SOURCES = [
  { source_id: 'sr-qa-scale-ai', ats_type: 'greenhouse', feed_url: 'https://boards-api.greenhouse.io/v1/boards/scaleai/jobs?content=true' },
  { source_id: 'sr-sa-alpaca',   ats_type: 'greenhouse', feed_url: 'https://boards-api.greenhouse.io/v1/boards/alpaca/jobs?content=true' },
  { source_id: 'sr-intl-wahed',  ats_type: 'lever',      feed_url: 'https://api.lever.co/v0/postings/wahed.com?mode=json' },
  { source_id: 'sr-sa-salla',    ats_type: 'workable',   feed_url: 'https://apply.workable.com/api/v1/widget/accounts/salla?details=true' },
];
return PILOT_SOURCES.map(s => ({ json: s }));

const provenanceRows = $input.all().map(i => i.json);
const provenanceById = new Map(provenanceRows.map(r => [r.id, r]));

const out = [];
for (const item of $('Load Approved Pilot Sources').all()) {
  const src = item.json;
  const prov = provenanceById.get(src.source_id);
  if (!prov) {
    out.push({ json: { ...src, company_name: null, review_status: null, automation_eligibility: null, approved: false, reviewReason: 'company_sources row not found for source_id' } });
    continue;
  }
  const approved = prov.review_status === 'verified' && prov.automation_eligibility === 'suitable_public_ats';
  out.push({
    json: {
      ...src,
      company_name: prov.company_name,
      review_status: prov.review_status,
      automation_eligibility: prov.automation_eligibility,
      approved,
      reviewReason: approved ? null : ('review_status=' + prov.review_status + ', automation_eligibility=' + prov.automation_eligibility),
    },
  });
}
return out;

const cfg = $('Workflow Configuration').first().json;
const results = $input.all().map(i => i.json);
const sum = (key) => results.reduce((acc, r) => acc + (r[key] || 0), 0);

const startedAtMs = new Date(cfg.startedAt).getTime();

return [{ json: {
  mode: cfg.mode,
  environment: cfg.environment,
  sourcesAttempted: results.length,
  sourcesSucceeded: results.filter(r => r.succeeded).length,
  sourcesFailed: results.filter(r => !r.succeeded).length,
  jobsFetched: sum('jobsFetched'),
  jobsValid: sum('jobsValid'),
  jobsRejected: sum('jobsRejected'),
  jobsCreated: sum('jobsCreated'),
  jobsUpdated: sum('jobsUpdated'),
  jobsUnchanged: sum('jobsUnchanged'),
  jobsClosed: sum('jobsClosed'),
  retries: sum('retries'),
  totalDurationMs: Date.now() - startedAtMs,
  perSource: results,
  finishedAt: new Date().toISOString(),
} }];

const src = $('Attach Provenance & Guard').item.json;
const evalResult = $input.first().json;
const retriesUsed = Math.max(0, (evalResult.attempt || 1) - 1);

if (!evalResult.success) {
  return [{ json: {
    source_id: src.source_id, ats_type: src.ats_type, company_name: src.company_name,
    outcome: evalResult.outcome, attempted: true, succeeded: false,
    jobsFetched: 0, jobsValid: 0, jobsRejected: 0,
    jobsCreated: 0, jobsUpdated: 0, jobsUnchanged: 0,
    retries: retriesUsed, error: evalResult.errorMessage, normalizedJobs: [],
  } }];
}

function stripHtml(html) {
  if (!html || typeof html !== 'string') return '';
  return html.replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
}

const body = evalResult.body || {};
const rawJobs = Array.isArray(body.jobs) ? body.jobs : [];
const normalized = [];
let rejected = 0;

for (const job of rawJobs) {
  const externalId = job.id != null ? String(job.id) : null;
  const title = typeof job.title === 'string' ? job.title.trim() : '';
  const applicationUrl = typeof job.absolute_url === 'string' ? job.absolute_url : null;
  const description = stripHtml(job.content);
  const locationName = job.location && typeof job.location.name === 'string' ? job.location.name : null;

  if (!externalId || !title || !applicationUrl || !/^https?:\/\//.test(applicationUrl) || !description) {
    rejected++;
    continue;
  }

  normalized.push({
    source_type: 'greenhouse', external_id: externalId, title, company_name: src.company_name,
    description, application_method: 'external_link', application_url: applicationUrl, status: 'active',
    location: locationName,
    work_arrangement: locationName && /remote/i.test(locationName) ? 'remote' : null,
    employment_type: null,
    source_id: src.source_id,
    published_at: job.first_published || null,
    source_last_modified_at: job.updated_at || null,
  });
}

return [{ json: {
  source_id: src.source_id, ats_type: src.ats_type, company_name: src.company_name,
  outcome: 'fetched', attempted: true, succeeded: true,
  jobsFetched: rawJobs.length, jobsValid: normalized.length, jobsRejected: rejected,
  jobsCreated: 0, jobsUpdated: 0, jobsUnchanged: 0,
  retries: retriesUsed, error: null, normalizedJobs: normalized,
} }];

const cfg = $('Workflow Configuration').first().json;
const cap = typeof cfg.maxJobsPerSource === 'number' ? cfg.maxJobsPerSource : 5;
const j = $input.first().json;
const seenExternalIds = new Set();
const dedupedJobs = [];
for (const job of j.normalizedJobs) {
  if (seenExternalIds.has(job.external_id)) continue;
  seenExternalIds.add(job.external_id);
  dedupedJobs.push(job);
}
const boundedJobs = dedupedJobs.slice(0, cap);
const truncated = dedupedJobs.length > cap;
return [{ json: {
  source_id: j.source_id, ats_type: j.ats_type, company_name: j.company_name,
  outcome: j.outcome, succeeded: j.succeeded,
  jobsFetched: j.jobsFetched, jobsValid: j.jobsValid, jobsRejected: j.jobsRejected,
  retries: j.retries, error: j.error,
  boundedJobs, truncated,
  externalIdList: boundedJobs.map(x => x.external_id),
} }];

const prepared = $('Prepare Bounded Write Set').item.json;
const boundedJobs = prepared.boundedJobs;
const fetchedIdSet = new Set(boundedJobs.map(j => j.external_id));

const existingRows = $input.all().map(i => i.json).filter(r => r && r.external_id);
const existingByExtId = new Map(existingRows.map(r => [r.external_id, r]));

let created = 0, updated = 0, unchanged = 0;
const nowIso = new Date().toISOString();
const upsertPayload = boundedJobs.map(job => {
  const existing = existingByExtId.get(job.external_id);
  if (!existing) {
    created++;
    return { ...job, first_seen_at: nowIso, last_seen_at: nowIso, last_checked_at: nowIso, last_successful_check_at: nowIso };
  }
  const changed = existing.title !== job.title || existing.description !== job.description
    || existing.application_url !== job.application_url || existing.location !== job.location
    || existing.work_arrangement !== job.work_arrangement || existing.employment_type !== job.employment_type;
  if (changed) updated++; else unchanged++;
  return { ...job, first_seen_at: existing.first_seen_at, last_seen_at: nowIso, last_checked_at: nowIso, last_successful_check_at: nowIso };
});

const staleExternalIds = existingRows.map(r => r.external_id).filter(extId => !fetchedIdSet.has(extId));

return [{ json: { ...prepared, upsertPayload, diffCreated: created, diffUpdated: updated, diffUnchanged: unchanged, staleExternalIds } }];

const plan = $('Compute Diff Plan').item.json;
const resultRaw = $input.first().json;
if (resultRaw && resultRaw.error) {
  return [{ json: { ...plan, writeSucceeded: false, jobsCreated: 0, jobsUpdated: 0, jobsUnchanged: 0, writeError: String(resultRaw.error).slice(0, 300) } }];
}
return [{ json: { ...plan, writeSucceeded: true, jobsCreated: plan.diffCreated, jobsUpdated: plan.diffUpdated, jobsUnchanged: plan.diffUnchanged, writeError: null } }];

const items = $input.all();
const out = [];
for (const item of items) {
  let j;
  try {
    j = $('Merge Upsert Result').item.json;
  } catch (e) {
    j = item.json;
  }
  out.push({ json: {
    source_id: j.source_id, ats_type: j.ats_type, company_name: j.company_name || null,
    outcome: j.writeSucceeded === false ? 'db_write_failed' : (j.outcome || 'unknown'),
    attempted: true,
    succeeded: j.writeSucceeded !== false && j.succeeded !== false,
    jobsFetched: j.jobsFetched || 0, jobsValid: j.jobsValid || 0, jobsRejected: j.jobsRejected || 0,
    jobsCreated: j.jobsCreated || 0, jobsUpdated: j.jobsUpdated || 0, jobsUnchanged: j.jobsUnchanged || 0,
    jobsClosed: Array.isArray(j.staleExternalIds) ? j.staleExternalIds.length : 0,
    retries: j.retries || 0,
    error: j.writeError || j.error || null,
    truncated: j.truncated === true,
  } });
}
return out;

