const src = $('Attach Provenance & Guard').item.json;
const inputItem = $input.first().json;
let attempt = 1;
try { attempt = $('Compute Backoff Greenhouse').item.json.attempt; } catch (e) { attempt = 1; }

const MAX_ATTEMPTS = 4;
const BASE_DELAY_MS = 500;
const MAX_DELAY_MS = 8000;
const RETRYABLE_5XX = new Set([500, 502, 503, 504]);

function computeBackoffMs(retryAfterMs) {
  if (typeof retryAfterMs === 'number' && retryAfterMs >= 0) return Math.min(MAX_DELAY_MS, retryAfterMs);
  const exp = Math.min(MAX_DELAY_MS, BASE_DELAY_MS * Math.pow(2, attempt - 1));
  const jitter = Math.random() * exp;
  return Math.min(MAX_DELAY_MS, Math.round((exp + jitter) / 2));
}

function retryableResult(kind, message, retryAfterMs) {
  const canRetry = attempt < MAX_ATTEMPTS;
  return [{ json: {
    source_id: src.source_id, ats_type: src.ats_type, company_name: src.company_name, feed_url: src.feed_url,
    success: false, shouldRetry: canRetry, attempt, nextAttempt: attempt + 1,
    nextDelayMs: canRetry ? computeBackoffMs(retryAfterMs) : null,
    outcome: canRetry ? kind : (kind + '_retries_exhausted'),
    errorMessage: message, statusCode: (inputItem && inputItem.statusCode) || null,
  } }];
}

function permanentResult(outcome, message, statusCode) {
  return [{ json: {
    source_id: src.source_id, ats_type: src.ats_type, company_name: src.company_name, feed_url: src.feed_url,
    success: false, shouldRetry: false, attempt, outcome, errorMessage: message, statusCode: statusCode || null,
  } }];
}

if (inputItem && inputItem.error) {
  return retryableResult('retryable_network_error', String(inputItem.error).slice(0, 300), null);
}

const statusCode = inputItem.statusCode;
if (statusCode === 429) {
  const headers = inputItem.headers || {};
  const retryAfterRaw = headers['retry-after'] || headers['Retry-After'];
  let retryAfterMs = null;
  if (retryAfterRaw != null) {
    const asSeconds = Number(retryAfterRaw);
    if (Number.isFinite(asSeconds) && asSeconds >= 0) {
      retryAfterMs = asSeconds * 1000;
    } else {
      const asDate = Date.parse(retryAfterRaw);
      if (!Number.isNaN(asDate)) retryAfterMs = Math.max(0, asDate - Date.now());
    }
  }
  return retryableResult('retryable_rate_limited', 'HTTP 429 from Greenhouse', retryAfterMs);
}
if (RETRYABLE_5XX.has(statusCode)) {
  return retryableResult('retryable_server_error', 'HTTP ' + statusCode + ' from Greenhouse', null);
}
if (statusCode >= 500) {
  return permanentResult('permanent_server_error', 'HTTP ' + statusCode + ' from Greenhouse', statusCode);
}
if (statusCode >= 400) {
  return permanentResult('permanent_client_error', 'HTTP ' + statusCode + ' from Greenhouse', statusCode);
}

return [{ json: {
  source_id: src.source_id, ats_type: src.ats_type, company_name: src.company_name, feed_url: src.feed_url,
  success: true, shouldRetry: false, attempt, outcome: 'fetched', statusCode, body: inputItem.body,
} }];

